python3 -c 'exec("import sys,json\nhasattr(sys,\"set_int_max_str_digits\") and sys.set_int_max_str_digits(0)\nJ=lambda x:json.dumps(x,separators=(\",\",\":\"),ensure_ascii=False)\ndef E(x):\n n=1\n for b in J(x).encode():n=n*257+b+1\n return n\ndef D(n):\n a=[]\n while n>1:\n  n,r=divmod(n,257)\n  if not r:raise ValueError(\"E257 digit\")\n  a.append(r-1)\n return json.loads(bytes(a[::-1]))\ndef R(x):\n if type(x)==int:return x\n if not isinstance(x,list) or not x:raise ValueError(\"AST\")\n op,*a=x\n if op==\"add\" and len(a)==2:return R(a[0])+R(a[1])\n if op==\"mul\" and len(a)==2:return R(a[0])*R(a[1])\n if op==\"pow\" and len(a)==2:\n  b,e=R(a[0]),R(a[1]);assert 0<=e<=4096;return b**e\n if op==\"pair\" and len(a)==2:\n  u,v=R(a[0]),R(a[1]);assert u>=0 and v>=0;return (u+v)*(u+v+1)//2+v\n if op==\"godel\" and len(a)==1:return E(a[0])\n if op==\"ungodel\" and len(a)==1:return D(R(a[0]))\n if op==\"dirichlet\" and len(a)==2:\n  N,s=R(a[0]),R(a[1]);assert 0<=N<=256 and 0<=s<=32\n  return [\"DirichletFormal\",[[(-1)**(n+1),n,s] for n in range(1,N+1)]]\n if op==\"feedback\" and len(a)==2:return [\"FeedbackFormal\",a[0],a[1]]\n raise ValueError(\"unsupported operation\")\nx=json.loads(sys.argv[1]) if len(sys.argv)>1 else [\"dirichlet\",4,2]\ny=R(x)\nprint(J({\"protocol\":\"HSI-OX-EISI/0.1\",\"input_godel\":str(E(x)),\"result\":y,\"result_godel\":str(E(y)),\"roundtrip\":D(E(y))==y,\"exact_integer\":True,\"numeric_analytic_evaluation\":False}))")' "$@"
